(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10 + Math.sin(x*0.05-y*0.03+t*0.7)*5;
  const wy = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10 + Math.cos(x*0.04+y*0.05-t*0.6)*5;
  const sx = x + wx, sy = y + wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*40, 0.14, 1.3],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75)*50, 0.11, 2.1],
    [200+Math.sin(t*0.7+4)*50, 220+Math.cos(t*0.3+3)*30, 0.09, 2.8]
  ];
  let aF=0, iF=0, aS=0, iS=0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aF += Math.sin(d*f - t*sp);
    iF += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    aS += Math.sin(d*f*1.5 - t*sp*1.3 + 0.8);
    iS += Math.sin(d*f*1.1 + t*sp*0.9 + 2.2);
  }
  const n = src.length;
  const act = (aF + aS*0.4)/n, inh = (iF + iS*0.4)/n;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.08+t*1.8)*Math.cos(sy*0.06-t*1.3)*0.15;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    + Math.sin(dist*0.08-ang*2-t*2.1)*0.15;
  const cX = sx*0.08, cY = sy*0.08;
  const ci = Math.floor(cX), cj = Math.floor(cY);
  let minD = 99;
  for (let di = -1; di <= 1; di++) for (let dj = -1; dj <= 1; dj++) {
    const nx = ci+di, ny = cj+dj;
    const px = nx + 0.5 + 0.4*Math.sin(nx*1.7+ny*2.3+t*0.4);
    const py = ny + 0.5 + 0.4*Math.cos(nx*2.1+ny*1.3+t*0.35);
    const d = Math.sqrt((cX-px)**2 + (cY-py)**2);
    if (d < minD) minD = d;
  }
  const voronoi = Math.cos(minD*Math.PI*2)*0.5+0.5;
  const reaction = Math.tanh((act - inh*0.7 + bg*0.3 + spiral + voronoi*0.15 - 0.5)*2.0);
  const micro = Math.sin(sx*0.3+t*3)*Math.sin(sy*0.3-t*2.5)*0.1;
  const blend = reaction*0.7 + micro*0.1 + (voronoi-0.5)*0.2;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,52],[12,45,85],[18,95,120],[25,150,130],[80,185,120],
    [180,200,80],[230,190,60],[220,140,55],[200,85,65],[160,50,75],
    [100,30,70],[55,20,65],[20,15,55],[5,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const sf = f*f*(3-2*f);
  const lum = 0.85 + Math.sin(reaction*Math.PI)*0.15;
  const edge = Math.abs(reaction)>0.65 ? 1.1+(Math.abs(reaction)-0.65)*0.5 : 1.0;
  const glow = Math.max(0, reaction-0.5)*0.3;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge + glow*60)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge + glow*40)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge + glow*20)|0)
  ];
}
